#include <bits/stdc++.h>
using namespace std;

const int MAX_SIZE = (1 << 19) | 5;
int total_numbers, exponent, modulus, max_value, count[MAX_SIZE], f_array[MAX_SIZE];
int tmp1_arr[20][MAX_SIZE], tmp2_arr[20][MAX_SIZE], tmp3_arr[20][MAX_SIZE];
long long power_product;
long long transform[20][MAX_SIZE];
long long factorial[MAX_SIZE], inv_factorial[MAX_SIZE];

long long fastExponentiation(long long base, long long exp) {
    long long result = 1, current = base;
    while (exp > 0) {
        if (exp & 1) result = result * current % modulus;
        current = current * current % modulus;
        exp >>= 1;
    }
    return result;
}

void initialize() {
    factorial[0] = 1;
    for (int i = 1; i <= max_value; i++)
        factorial[i] = factorial[i - 1] * i % modulus;
    inv_factorial[max_value] = fastExponentiation(factorial[max_value], modulus - 2);
    for (int i = max_value - 1; i >= 0; i--)
        inv_factorial[i] = inv_factorial[i + 1] * (i + 1) % modulus;
}

int get_lower_power(int x) {
    int power = 1;
    while (power < x) power <<= 1;
    return power;
}

void FWT_transform(int *array, int length, bool inverse = false) {
    long long *temp = transform[0];
    for (int i = 0; i < length; i++) temp[i] = array[i];
    for (int step = 1; step < length; step <<= 1) {
        for (int j = 0; j < length; j += (step << 1)) {
            for (int k = j; k < j + step; k++) {
                long long val = temp[k];
                if (inverse) {
                    temp[k + step] -= val;
                } else {
                    temp[k + step] += val;
                }
            }
        }
    }
    for (int i = 0; i < length; i++) {
        array[i] = (int)(temp[i] % modulus);
        if (array[i] < 0) array[i] += modulus;
    }
}

inline void adjust_mod(long long &x) { if (x >= power_product) x -= power_product; }

void multiply() {
    memset(tmp1_arr, 0, sizeof tmp1_arr);
    memset(transform, 0, sizeof transform);
    for (int i = 0; i <= max_value; i++)
        tmp1_arr[count[i]][i] = f_array[i];
    for (int j = 0; j <= 19; j++)
        FWT_transform(tmp1_arr[j], max_value + 1);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; l + q <= 19; l++)
            for (int s = 0; s <= max_value; s++)
                adjust_mod(transform[q + l][s] += 1LL * tmp1_arr[q][s] * tmp2_arr[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= max_value; s++)
            tmp3_arr[q][s] = (int)(transform[q][s] % modulus);
    for (int j = 0; j <= 19; j++)
        FWT_transform(tmp3_arr[j], max_value + 1, true);
    for (int j = 0; j <= max_value; j++)
        f_array[j] = tmp3_arr[count[j]][j];
}

void multiply_second() {
    static int temp[20][MAX_SIZE];
    for (int i = 0; i <= 19; i++)
        memset(transform[i], 0, sizeof(long long) * (max_value + 1));
    for (int q = 0; q <= 19; q++)
        for (int l = 0; l + q <= 19; l++)
            for (int s = 0; s <= max_value; s++)
                adjust_mod(transform[q + l][s] += 1LL * tmp2_arr[q][s] * tmp2_arr[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= max_value; s++)
            temp[q][s] = (int)(transform[q][s] % modulus);
    for (int i = 0; i <= 19; i++)
        FWT_transform(temp[i], max_value + 1, true);
    for (int i = 0; i <= 19; i++)
        memset(tmp2_arr[i], 0, sizeof(int) * (max_value + 1));
    for (int i = 0; i <= max_value; i++)
        tmp2_arr[count[i]][i] = temp[count[i]][i];
    for (int i = 0; i <= 19; i++)
        FWT_transform(tmp2_arr[i], max_value + 1);
}

int main() {
    scanf("%d%d%d", &total_numbers, &exponent, &modulus);
    power_product = 1LL * modulus * modulus;
    if (total_numbers & 1) {
        printf("%lld", fastExponentiation(exponent, total_numbers));
        return 0;
    }
    f_array[0] = 1;
    max_value = get_lower_power(total_numbers + 1) - 1;
    initialize();
    for (int i = 0; i <= max_value; i++)
        count[i] = __builtin_popcount(i);
    for (int i = 0; i <= max_value; i++)
        tmp2_arr[count[i]][i] = inv_factorial[i];
    for (int i = 0; i <= 19; i++)
        FWT_transform(tmp2_arr[i], max_value + 1);
    int res = exponent;
    while (res) {
        if (res & 1) multiply();
        res >>= 1;
        if (res) multiply_second();
    }
    printf("%lld", (fastExponentiation(exponent, total_numbers) - factorial[total_numbers] * f_array[total_numbers] % modulus + modulus) % modulus);
    return 0;
}
